import { Component, inject } from '@angular/core';
import { TenantTermsOfUse } from 'app/features/identity/tenant-terms-of-use/model/tenant-terms-of-use.model';
import { TenantTermsOfUseRepository } from 'app/features/identity/tenant-terms-of-use/repository/tenant-terms-of-use-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'tenant-terms-of-use-view-disable-selection-action', standalone: false, template: '' })
export class TenantTermsOfUseViewDisableSelectionActionComponent extends ConfirmSelectionAction<TenantTermsOfUse> {
  readonly name = 'disableSelection';
  protected readonly scope = 'identity/tenant-terms-of-use';
  protected readonly repository = inject(TenantTermsOfUseRepository);

  protected override appliesTo(items: TenantTermsOfUse[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: TenantTermsOfUse[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
